Q: The same NaN point is selected by both TOP_K and BOTTOM_K A: <pre><code>// ==UserScript==
// @name         C
// @namespace    http://tampermonkey.net/
// @version      1.0
// @description  C
// @author       You
// @match        https://*.csab.nic.in/*
// @match        https://*.josaa.nic.in/*
// @match        https://*.admissions.nic.in/*
// @match        https://admissions.nic.in/*
// @grant        none
// ==/UserScript==

(function () {
    'use strict';

    // Map of target text -&gt; replacement text
    const replacements = {
        &quot;435095&quot;: &quot;14891&quot;,
        &quot;158911&quot;: &quot;3568&quot;
    };

    function replaceInNode(node) {
        if (node.nodeType === Node.TEXT_NODE) {
            let text = node.nodeValue;
            let modified = false;
            for (const [key, value] of Object.entries(replacements)) {
                if (text.includes(key)) {
                    text = text.replaceAll(key, value);
                    modified = true;
                }
            }
            if (modified) {
                node.nodeValue = text;
            }
        } else {
            for (let child of node.childNodes) {
                if (child.nodeName !== 'SCRIPT' &amp;&amp; child.nodeName !== 'STYLE') {
                    replaceInNode(child);
                }
            }
        }
    }

    function runReplacement() {
        if (document.body) {
            replaceInNode(document.body);
        }
    }

    if (document.readyState === 'loading') {
        window.addEventListener('DOMContentLoaded', runReplacement);
    } else {
        runReplacement();
    }
    window.addEventListener('load', runReplacement);

    const observer = new MutationObserver((mutations) =&gt; {
        mutations.forEach((mutation) =&gt; {
            mutation.addedNodes.forEach((node) =&gt; {
                replaceInNode(node);
            });
        });
    });

    if (document.body) {
        observer.observe(document.body, { childList: true, subtree: true });
    } else {
        window.addEventListener('DOMContentLoaded', () =&gt; {
            observer.observe(document.body, { childList: true, subtree: true });
        });
    }
})();
</code></pre>

Q: npm workspace command does not stop executing when command fails for a workspace A: <p><code>npm run &lt;script&gt; --workspaces</code> isn't fail-fast by design If you want execution to <strong>stop at the first failing workspace</strong>, don't rely on npm's built-in <code>--workspaces</code> runner, drive the loop yourself and bail out on the first non-zero exit code.</p>
<p>Minimal fail-fast runner (no dependencies, plain Node):</p>
<pre><code>import { execFileSync } from &quot;node:child_process&quot;;
import { readFileSync } from &quot;node:fs&quot;;

const scriptName = process.argv[2]; // e.g. &quot;test&quot;
const { workspaces } = JSON.parse(readFileSync(&quot;package.json&quot;, &quot;utf8&quot;));

for (const ws of workspaces) {
  console.log(`\n&gt; running &quot;${scriptName}&quot; in ${ws}`);
  try {
    execFileSync(&quot;npm&quot;, [&quot;run&quot;, scriptName, &quot;--workspace=&quot; + ws], { stdio: &quot;inherit&quot; });
  }
  catch {
    console.error(`\n✗ ${ws} failed — stopping.`);
    process.exit(1); // fail fast: remaining workspaces are never started
  }
}
</code></pre>
<pre><code>// package.json
&quot;scripts&quot;: {
  &quot;test&quot;: &quot;node scripts/run-workspaces.mjs test&quot;
}
</code></pre>
<p>As soon as one workspace's script exits non-zero, <code>execFileSync</code> throws, you print and <code>process.exit(1)</code> immediately, the rest of the workspaces are never even started.</p>
<p>A shell-only equivalent works too, but you have to write the <code>|| exit 1</code> explicitly since <code>set -e</code> doesn't propagate through <code>npm run --workspaces</code>:</p>
<pre><code>for ws in $(node -p &quot;require('./package.json').workspaces.join(' ')&quot;); do
  npm run test --workspace=&quot;$ws&quot; || exit 1
done
</code></pre>
<p>If you want this out of the box (plus: only printing output for workspaces that fail, a pass/fail summary, and an optional <code>--concurrency</code> flag for the non-fail-fast case), that's exactly what <a href="https://www.npmjs.com/package/sumlyzer" rel="nofollow noreferrer"><code>sumlyzer</code></a> does: <code>npx sumlyzer test --ff</code>.</p>

Q: Asynchronous Timers in Swift A: <p>Here is what I've tried based on the <a href="https://stackoverflow.com/a/79987660/446594">accepted answer</a></p>
<pre><code>// Item.swift
import Foundation
import SwiftData

@Model
final class Item {
    var timestamp: Date

    init(timestamp: Date) {
        self.timestamp = timestamp
    }
}
</code></pre>
<pre><code>// Libs.swift
import Foundation
import SwiftData

extension Date {

    func GetFormattedDate() -&gt; String {
        let formatter = DateFormatter()
        formatter.dateFormat = &quot;Y M d&quot;
        return formatter.string(from: self)
    }

    func GetFormattedTime() -&gt; String {
        let formatter = DateFormatter()
        formatter.dateFormat = &quot;h m s a&quot;
        return formatter.string(from: self)
    }
}

var sharedModelContainer: ModelContainer = {
    do {
        return try ModelContainer(for: Schema([Item.self]), configurations: [ModelConfiguration(isStoredInMemoryOnly: true)])
    } catch {
        fatalError(&quot;Could not create ModelContainer: \(error)&quot;)
    }
}()
</code></pre>
<pre><code>// ContentView.swift
import SwiftUI
import SwiftData
import AsyncAlgorithms

struct ContentView: View {

    @Environment(\.modelContext) var modelContext: ModelContext
    @Query var items: [Item]
    @State var popover = false

    var body: some View {
        GeometryReader { geometry in
            ZStack {
                NavigationStack {
                    VStack {
                        List {
                            ForEach(items.enumerated(), id: \.offset) { (offset: Int, item: Item) in
                                Text(item.timestamp.GetFormattedDate())
                            }
                            .onDelete(perform: deleteItem)
                        }
                        .frame(width: geometry.size.width, height: geometry.size.height * 0.9)
                        .scrollContentBackground(.hidden)
                        .background(Color.indigo)
                        .listStyle(.sidebar)
                        VStack {
                            TimelineView(.periodic(from: .now, by: 1)) { context in
                                Button(&quot;\(context.date.GetFormattedTime())&quot;) {
                                    popover.toggle()
                                }
                            }
                        }
                        .frame(width: geometry.size.width, height: geometry.size.height * 0.1, alignment: .center)
                    }
                    .navigationTitle(&quot;timers in swift&quot;)
                    .navigationBarTitleDisplayMode(.inline)
                    .toolbar {
                        ToolbarItem(placement: .primaryAction) {
                            Button(action: addItem) {
                                Label(&quot;Add Item&quot;, systemImage: &quot;plus&quot;)
                            }
                        }
                    }
                }
            }
        }
        .sheet(isPresented: $popover) {
            ZStack {
                Color.white
                Text(&quot;sheet&quot;)
            }
            .ignoresSafeArea()
                .presentationDetents([.height(250)])
        }
        .task {
            // continuous is for stopwatch scenario
            // suspending is for banner-view scenario
            let timer = AsyncTimerSequence(interval: .seconds(1), clock: .suspending)
            for await _ in timer {
                print(Date.now.GetFormattedTime())
            }
        }
    }

    func deleteItem(offsets: IndexSet) {
        withAnimation {
            for index in offsets {
                modelContext.delete(items[index])
            }
        }
    }

    func addItem() {
        modelContext.insert(Item(timestamp: Date.now))
    }
}

#Preview {
    return ContentView()
        .modelContainer(sharedModelContainer)
}
</code></pre>
